**Root cause:** Next 16 `dashboardGuard` in the root `middleware.ts` runs for every `/api/*` path and 401s anything without a dashboard session cookie. Federation API calls authenticate with a **Bearer token** (enforced by the route-layer `roleGuard`), not the dashboard session — so valid token calls died at the middleware before the handler ever ran. `PUBLIC_API_PATHS` simply didn't list the `/api/federation` prefix.

**Fix:** allowlist the federation prefix in the middleware so token-authenticated traffic reaches the route layer; keep `roleGuard` as the token authority so missing/bad tokens still 401 (defense in depth).

```ts
// middleware.ts (Next 16 also accepts proxy.ts — same body, same matcher)
import { NextResponse, type NextRequest } from "next/server";

/**
 * Paths that authenticate at the ROUTE layer (roleGuard / Bearer token),
 * not with the dashboard session cookie. They must bypass dashboardGuard,
 * otherwise valid token calls 401 before the handler is reached.
 */
const PUBLIC_API_PATHS = [
  "/api/auth",
  "/api/health",
  "/api/federation", // ← FIX: token auth enforced by route-layer roleGuard
] as const;

function matchesPublicPath(pathname: string): boolean {
  return PUBLIC_API_PATHS.some(
    (p) => pathname === p || pathname.startsWith(`${p}/`), // handles trailing-slash & subpaths
  );
}

export function dashboardGuard(req: NextRequest) {
  const { pathname } = req.nextUrl; // query string excluded by Next

  // Token-authenticated routes pass through; roleGuard enforces the token.
  if (matchesPublicPath(pathname)) return NextResponse.next();

  // Everything else (other /api/* and /dashboard/*) needs a dashboard session.
  const session = req.cookies.get("dashboard_session");
  if (!session?.value) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }
  // ... verify session signature/expiry ...
  return NextResponse.next();
}

export function middleware(req: NextRequest) {
  return dashboardGuard(req);
}

// Matcher MUST cover the federation prefix so the allowlist runs;
// non-allowlisted /api paths still hit dashboardGuard and 401.
export const config = {
  matcher: ["/api/:path*", "/dashboard/:path*"],
};
```

Route layer stays unchanged — it is the single token authority:

```ts
// lib/role-guard.ts
export async function roleGuard(req: Request): Promise<Auth> {
  const token = req.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
  if (!token) throw new ApiError(401, "missing bearer token");
  const auth = await verifyFederationToken(token); // JWT/jwks check
  if (!auth) throw new ApiError(401, "invalid token");
  return auth;
}

// app/api/federation/peers/route.ts
import { roleGuard } from "@/lib/role-guard";
import { ApiError } from "@/lib/api-error";

export async function GET(req: Request) {
  const auth = await roleGuard(req); // 401 on missing/bad token
  const peers = await federationClient.listPeers(auth.sub);
  return NextResponse.json({ peers });
}
```

Note the one-line semantic: prefix check uses `pathname === p || pathname.startsWith(p + "/")` so `/api/federation` and `/api/federation/peers` pass, while a sibling prefix like `/api/federation-events` correctly does **not** match.
